import{_ as s,o as t,c as i,a6 as a}from"./chunks/framework.CKIbuWFA.js";const f=JSON.parse('{"title":"Utiliser TikTools","description":"","frontmatter":{"title":"Utiliser TikTools","docId":"user.overview","translationKey":"user.overview","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"72ce37218d4f3341fccd306bd0b1b4039ec6e1fd3dcfeb16f9096f43576c861d","translationRevision":"0a6890b291813b3745dc16275a79aacfe946cbb112edc0227a48cc2a79175aca","order":0},"headers":[],"relativePath":"fr/user/index.md","filePath":"fr/user/index.md","lastUpdated":1794611623000}'),n={name:"fr/user/index.md"};function o(r,e,l,u,c,d){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="use-tiktools" tabindex="-1">Utiliser TikTools <a class="header-anchor" href="#use-tiktools" aria-label="Permalink to &quot;Utiliser TikTools {#use-tiktools}&quot;">​</a></h1><p>TikTools connecte un ordinateur Windows ou Linux à un TikTok LIVE, affiche ses événements, conserve les points des spectateurs et exécute des règles sur votre ordinateur. L’interface de bureau et l’hôte sans interface graphique facultatif partagent le même cœur Rust. Un compte Cloud est distinct de la connexion TikTok.</p><h2 id="choose-your-first-task" tabindex="-1">Choisir votre première tâche <a class="header-anchor" href="#choose-your-first-task" aria-label="Permalink to &quot;Choisir votre première tâche {#choose-your-first-task}&quot;">​</a></h2><ol><li>Vérifiez les <a href="./requirements.html">prérequis</a> et <a href="./installation.html">installez un binaire publié</a>. Rust, Cargo et Bun ne sont pas nécessaires pour utiliser la version de bureau.</li><li><a href="./first-live.html">Connectez-vous à un LIVE</a>, en commençant sans cookie TikTok lorsque la salle autorise l’accès invité.</li><li>Utilisez <strong>Live feed</strong> pour examiner les événements. <strong>Points</strong> conserve les totaux des spectateurs ; <strong>Analytics</strong> affiche les statistiques. <strong>Automations</strong> relie des déclencheurs aux actions configurées.</li><li>Installez des intégrations facultatives depuis <strong>Plugins</strong>. Les paquets de plugins externes sont distribués séparément de l’application.</li><li>Utilisez <strong>Overlays</strong> pour préparer une source navigateur pour OBS. L’intégration de passerelle est nécessaire pour diffuser les widgets en direct.</li></ol><h2 id="available-and-experimental-features" tabindex="-1">Fonctionnalités disponibles et expérimentales <a class="header-anchor" href="#available-and-experimental-features" aria-label="Permalink to &quot;Fonctionnalités disponibles et expérimentales {#available-and-experimental-features}&quot;">​</a></h2><p>La navigation principale présente Live feed, Points, Analytics, Connections, Automations, Plugins, Overlays et Settings. Les classements et compétitions disposent d’un moteur natif et d’une route directe, mais leur page de gestion reste masquée dans la navigation habituelle. Ne supposez pas que tous les prototypes décrits dans un ancien document de conception sont des fonctionnalités publiées.</p><p>Les changements Cloud des plugins et les Variables examinées utilisent des commandes explicites par section. Automations effectue actuellement une comparaison avec une copie de référence locale ; ce bouton ne publie pas de profils sur Cloud. Les transports de collaboration et certains transferts vers les installateurs restent expérimentaux. Une commande désactivée indique généralement une capacité absente de l’hôte ou un prérequis non satisfait.</p><h2 id="when-something-fails" tabindex="-1">En cas d’échec <a class="header-anchor" href="#when-something-fails" aria-label="Permalink to &quot;En cas d’échec {#when-something-fails}&quot;">​</a></h2><p>Ouvrez <strong>Diagnostics</strong>, conservez la source de l’erreur et l’identifiant de requête, et notez la version installée. Évitez d’inclure des cookies, jetons d’invitation ou valeurs de variables privées. Commencez par la procédure de récupération de chaque guide, puis consultez les guides d’assistance. La démo interactive utilise des données fictives et ne permet pas de vérifier votre compte TikTok, OBS ou votre réseau.</p><p>Pour développer le code source, consultez la <a href="./../developer/">documentation de développement</a>.</p>',10)])])}const m=s(n,[["render",o]]);export{f as __pageData,m as default};
